message.content:
{
  "sections": [
    {
      "title": "Why you were in the hospital",
      "bullets": [
        {
          "id": "b1",
          "text": "Your heart does not pump as strongly as it should and got worse. Your heart pumps at 30 percent.",
          "sources": ["p1:L6", "term:CHF", "term:EF"]
        },
        {
          "id": "b2",
          "text": "You have narrowed blood vessels in the heart and had a tube put in to open a blocked artery. You also have high blood pressure.",
          "sources": ["p1:L7", "term:CAD", "term:PCI", "term:HTN"]
        }
      ]
    },
    {
      "title": "What to do at home",
      "bullets": [
        {
          "id": "b3",
          "text": "Eat a low salt diet. Limit salt to 2 grams each day.",
          "sources": ["p1:L19"]
        },
        {
          "id": "b4",
          "text": "Drink no more than 1.5 liters of fluid each day.",
          "sources": ["p1:L19"]
        },
        {
          "id": "b5",
          "text": "Weigh yourself every morning before breakfast and write it down.",
          "sources": ["p1:L20"]
        },
        {
          "id": "b6",
          "text": "Do not lift anything over 10 pounds for 1 week.",
          "sources": ["p1:L21"]
        }
      ]
    },
    {
      "title": "Your follow-up visits",
      "bullets": [
        {
          "id": "b7",
          "text": "See Dr. Okafor, your heart doctor. Go in 1 week. This visit checks your heart.",
          "sources": ["p1:L23"]
        },
        {
          "id": "b8",
          "text": "Get a blood test for salts and kidneys. Go in 3 days. This test checks your potassium and kidney function.",
          "sources": ["p1:L24", "term:BMP"]
        },
        {
          "id": "b9",
          "text": "See your family doctor. Go in 2 weeks.",
          "sources": ["p1:L25", "term:PCP"]
        }
      ]
    }
  ],
  "questions_for_your_doctor": [
    "What should I do if my weight goes up fast?",
    "Can I take my usual medicines on the day of the blood test?",
    "When can I start lifting more than 10 pounds?"
  ]
}
